package expo.modules.linking

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import expo.modules.core.interfaces.ReactActivityLifecycleListener

class LinkingReactActivityLifecycleListener : ReactActivityLifecycleListener {
  override fun onCreate(activity: Activity?, savedInstanceState: Bundle?) {
    onReceiveURL(activity?.intent?.data)
  }

  override fun onNewIntent(intent: Intent?): Boolean {
    onReceiveURL(intent?.data)
    return true
  }
  
  // Explicitly implement all interface methods to fix AbstractMethodError with expo-modules-core@3.0.29
  // These methods have default implementations in Java but need explicit overrides in Kotlin
  // when compiled against older expo-modules-core versions
  override fun onResume(activity: Activity) {
    // No-op implementation for expo-linking
  }
  
  override fun onPause(activity: Activity) {
    // No-op implementation for expo-linking
  }
  
  override fun onUserLeaveHint(activity: Activity) {
    // No-op implementation for expo-linking
  }
  
  override fun onDestroy(activity: Activity) {
    // No-op implementation for expo-linking
  }
  
  override fun onBackPressed(): Boolean {
    // No-op implementation for expo-linking
    return false
  }
  
  override fun onContentChanged(activity: Activity) {
    // No-op implementation for expo-linking
  }

  private fun onReceiveURL(url: Uri?) {
    if (url == null) {
      return
    }
    ExpoLinkingModule.initialURL = url
    ExpoLinkingModule.onURLReceivedObservers.forEach { it -> it(url) }
  }
}
